var a=125;var o=`125-cheese-melting-and-texture`;var s=`117`;var i={en:`Cheese Melting and Texture`,ua:`Плавлення сиру та його текстура`};var n={short:`Cheeses melt differently because their protein networks, acidity, calcium, moisture and fat content differ. Heat can produce a smooth flow, stretchy strands, or a softened cheese that barely spreads.`,sections:[{title:`Core idea`,text:`Casein forms the cheese matrix. Its mineral cross-links, breakdown during aging and hydration determine how freely the softened protein network can move as fat melts.`},{title:`Scientific / practical principles`,text:`Mozzarella can become elastic and stringy; mature cheeses may soften but release fat; acid–heat cheeses such as paneer retain their shape. Excessive heat drives moisture loss and protein contraction, producing rubbery clumps or oil separation.`},{title:`How to apply it`,text:`For a smooth cheese sauce, use low to moderate heat and add grated cheese gradually to a moist base. Choose cheeses for desired stretch or flow rather than only flavor. If a sauce splits, gentle cooling and controlled liquid addition may help, but not every cheese can become fluid.`},{title:`Practical example`,text:`Warm equal small amounts of mozzarella, hard aged cheese and paneer in separate covered dishes. Record stretch, separation of fat and shape retention; avoid assuming all three have the same melting point.`},{title:`Common mistakes and limitations`,text:`A cheese being hot does not guarantee it will melt smoothly. Meltability also depends on manufacturing and aging, not only fat percentage. Dairy cheese contains milk allergens even when cooked.`},{title:`Choosing cheese for the dish`,text:`For pizza, elastic melting may be desirable; for a creamy sauce, controlled dispersion into a wet base matters more. Paneer and similar acid-set cheeses often retain their shape. Raising the heat to force a non-melting cheese to flow tends to create oil separation or toughness.`},{title:`Related theories`,text:`056, 123, 169, 174.`}]};var r={short:`Сири плавляться по-різному через відмінності білкової сітки, кислотності, кальцію, води та жиру. Нагрів може дати плавну масу, тягучі нитки або м’який сир, який майже не розтікається.`,sections:[{title:`Суть`,text:`Казеїн формує основу сиру. Мінеральні зв’язки, розщеплення білка під час дозрівання та вміст води визначають рухливість білкової сітки після розм’якшення і плавлення жиру.`},{title:`Наукові та практичні принципи`,text:`Моцарела стає еластичною і тягучою; витримані сири можуть розм’якшуватися та виділяти жир; кислотно-термічні сири на кшталт паніру зберігають форму. Надмірний жар виганяє воду, ущільнює білки й спричиняє гумові грудки чи відділення олії.`},{title:`Як застосовувати`,text:`Для гладкого сирного соусу використовуйте невисокий нагрів і поступово додавайте натертий сир до вологої основи. Підбирайте сир не лише за смаком, а й за бажаною тягучістю. Якщо соус розділився, інколи допомагають помірне охолодження й обережне додавання рідини.`},{title:`Практичний приклад`,text:`Нагрійте однакові невеликі порції моцарели, витриманого твердого сиру й паніру в окремому посуді. Порівняйте тягучість, виділення жиру та збереження форми; не вважайте, що всі вони мають однакову температуру плавлення.`},{title:`Поширені помилки й обмеження`,text:`Гарячий сир не обов’язково плавиться рівномірно. На плавкість впливають технологія виробництва й дозрівання, а не тільки частка жиру. Термічно оброблений сир усе одно містить молочні алергени.`},{title:`Вибір сиру для страви`,text:`Для піци потрібна еластичність, а для вершкового соусу потрібне рівномірне розподілення сиру у вологій основі. Панір та подібні кислотно-зсіджені сири часто зберігають форму. Надмірний жар зазвичай не примушує їх плавитися, а спричиняє жорсткість чи відділення жиру.`},{title:`Пов’язані теорії`,text:`056, 123, 169, 174.`}]};var l=[56,123,169,174];var c=`References / Джерела`;var d=[`https://www.ncbi.nlm.nih.gov/books/NBK562892/box/box002/?report=objectonly`,`https://books.lib.uoguelph.ca/dairyscienceandtechnologyebook/chapter/cultured-dairy-products-and-cheese/`];var h={id:125,slug:o,group:`117`,title:i,en:n,ua:r,related:l,referenceTitle:c,references:d};export{h as default,n as en,s as group,a as id,c as referenceTitle,d as references,l as related,o as slug,i as title,r as ua};